/**
 * The Korean "All forms" table: what a LEARNER can read for a word, generated by rule from the lexicon row (the `ko` adapter's
 * `paradigm` and the context-aware half of `featuresFromTableTags`).
 *
 * A predicate (verb, descriptive verb, the copulas, 있다 / 없다 and the honorific lexemes) gets ONE table of slots (rows) by
 * column (plain, honorific -(으)시-), in this order: the three stem shapes; statements, questions, commands and suggestions at the four
 * speech levels (and, for statements, past and -겠-); five-plus connectives; what the word is before a noun; the word as a noun. Every
 * form comes from `koGenerate` (the same engine the analyser reads with) over the lexicon row's own conjugation class; a descriptive verb
 * has no -는다, no command and no suggestion, so those cells are left out, never filled with a wrong form. A noun, pronoun or numeral gets
 * the common particles, chosen by its last sound, and the copula forms (학생이다, 의사다).
 *
 * A bare lemma that names several entries (눈, 묻다 of a balanced set) gets a table ONLY when every candidate conjugates identically;
 * otherwise one table per conjugation class, each labelled by its entry (`Entry`), never silently the first.
 *
 * The dictionary half of the card (`buildParadigm` in the extension) maps Wiktionary's table rows through `featuresFromTableTags`. That
 * call does not carry the lemma, and the dictionary's second (honorific) table repeats the first table's tags; so the generator leaves
 * the forms it just generated in `CONTEXT` and `koFeaturesFromTableTags` reads them: a row whose form the plain cell spells is the plain
 * cell, one the honorific cell spells is the honorific cell, one neither spells goes to the cell its shape says (a disagreement then
 * shows as a conflict on the right cell, never on a neighbour). This is the one piece of state in the module; it is set by every
 * `paradigm()` call and cleared at its start.
 */
import type { GeneratedParadigm, PartOfSpeech, ParadigmLayout } from '../../core';
import { koGenerate, koJunctionBases, koShapeClasses, KO_HONORIFIC_SI_STEMS, type KoConjClass } from './conjugate';
import { koEnding } from './endings';
import { koBareLemma, koEntryLemma, koHomonymNumber, koSharedPos, koStemKey, lookupKoreanStem, type KoLexEntry } from './index-store';
import { koAllomorphAgrees, KO_CLOSED_PREDICATES, PARTICLES } from './particles';
import { KO_CONNECTIVE_SLOTS, KO_LEVELS, koCellFeatures, koFeaturesFromTableTagsPlain, type KoLevel, type KoMood, type KoTense } from './tags';
import { decompose, FINALS, VOWELS } from './hangul';

export type KoCat = 'V' | 'A' | 'E' | 'C' | 'N';

export interface KoRow {
  /** The entry's headword (묻다). */
  lemma: string;
  /** The lemma string the card carries for it (묻다¹, or the bare headword of a main entry). */
  shown: string;
  stem: string;
  cls: KoConjClass;
  cat: KoCat;
  /** The lexeme is itself honorific and ends in 시 (계시다, 드시다): no honorific column; 시 + 어요 → 세요. */
  honSi: boolean;
  gloss?: string;
  entry: KoLexEntry;
}

// ───────────────────────────── the rows of the lexicon for a lemma ─────────────────────────────

const PREDICATE_TAGS: Readonly<Record<string, readonly string[]>> = { VERB: ['VV', 'VX'], ADJ: ['VA', 'VCN'], AUX: ['VCP', 'VCN', 'VX', 'VA', 'VV'] };
const EXIST = /[있없밌]$/u;

function categoryOf(entry: KoLexEntry, stem: string): KoCat {
  if (entry.tag === 'VCP') return 'C';
  if (entry.tag === 'VCN') return 'N';
  if (EXIST.test(stem)) return 'E';
  return entry.tag === 'VA' ? 'A' : 'V';
}

/** The predicate rows the lexicon (and the closed table of copulas and existentials) holds for a lemma and part of speech: the numbered homonym a numbered lemma names, else every entry of a bare spelling. */
export function koPredicateRows(lemma: string, pos: string): { rows: KoRow[]; refused: string[] } {
  const bare = koBareLemma(lemma);
  const refused: string[] = [];
  if (!bare.endsWith('다') || bare.length < 2) return { rows: [], refused };
  const key = koStemKey(bare, 'VV');
  const seen = new Set<string>();
  const entries: KoLexEntry[] = [];
  // 이다 and 아니다 are the closed copulas (the lexicon holds 이다² "to carry on the head" and a descriptive 아니다 that the closed table replaces); a numbered 이다² is the lexicon's
  const closedOnly = lemma === '이다' || lemma === '아니다';
  const closed = (KO_CLOSED_PREDICATES.get(key) ?? []).filter((e) => e.lemma === bare);
  for (const e of closedOnly ? closed : [...lookupKoreanStem(key).map((h) => h.entry), ...closed]) {
    if (e.lemma !== bare || !PREDICATE_TAGS.VERB.concat(PREDICATE_TAGS.ADJ, PREDICATE_TAGS.AUX).includes(e.tag)) continue;
    const id = `${e.tag}|${e.hom ?? 0}`;
    if (seen.has(id)) continue;
    seen.add(id);
    entries.push(e);
  }
  const prefer = closedOnly ? PREDICATE_TAGS.AUX : PREDICATE_TAGS[pos] ?? [];
  let pool: KoLexEntry[] = [];
  for (const tag of prefer) { pool = entries.filter((e) => e.tag === tag); if (pool.length) break; }
  if (!pool.length && !PREDICATE_TAGS[pos] && !closedOnly) return { rows: [], refused };
  if (!pool.length) pool = entries;
  const numbered = koHomonymNumber(lemma) !== undefined;
  let chosen = pool.filter((e) => koEntryLemma(e) === lemma);
  if (!chosen.length && !numbered) chosen = pool;
  const stem = bare.slice(0, -1);
  const rows: KoRow[] = [];
  if (!chosen.length && !numbered && !closedOnly) {
    // a word the analyser builds from a known noun or root and a light verb (체포되다, 공부하다 when the lexicon holds only 공부) conjugates as its light verb does
    const light = [['시키', 'R'], ['하', 'Ha'], ['되', 'R']].find(([lv]) => stem.length > lv.length && stem.endsWith(lv)) as [string, KoConjClass] | undefined;
    const head = light ? stem.slice(0, -light[0].length) : '';
    if (light && lookupKoreanStem(head).some((h) => h.entry.lemma === head && ['NNG', 'NNP', 'XR', 'NR'].includes(h.entry.tag)) && (light[0] !== '되' || pos === 'VERB')) {
      const tag = pos === 'ADJ' ? 'VA' : 'VV';
      const entry: KoLexEntry = { lemma: bare, tag, irr: light[1] === 'Ha' ? 'Ha' : 'R', own: true };
      return { rows: [{ lemma: bare, shown: bare, stem, cls: light[1], cat: tag === 'VA' ? 'A' : 'V', honSi: false, entry }], refused };
    }
  }
  for (const entry of chosen) {
    let cls: KoConjClass | undefined = entry.tag === 'VCP' ? 'Cop' : entry.tag === 'VCN' ? 'Neg' : entry.irr;
    if (!cls) {
      // the source gives this entry no conjugation table: a shape that could be irregular is not guessed
      if (koShapeClasses(stem).length) { refused.push(`${koEntryLemma(entry)}: the dictionary gives no conjugation class and the stem's shape allows an irregular one`); continue; }
      cls = 'R';
    }
    const honSi = stem.endsWith('시') && (KO_HONORIFIC_SI_STEMS.has(stem) || /honorific/iu.test(entry.gloss ?? ''));
    rows.push({ lemma: bare, shown: koEntryLemma(entry), stem, cls, cat: categoryOf(entry, stem), honSi, ...(entry.gloss ? { gloss: entry.gloss } : {}), entry });
  }
  rows.sort((a, b) => (a.entry.hom ?? 0) - (b.entry.hom ?? 0));
  return { rows, refused };
}

// ───────────────────────────── slots, chains, forms ─────────────────────────────

const MOODS: ReadonlyArray<readonly [KoMood, string]> = [['Ind', 'statement'], ['Int', 'question'], ['Imp', 'command'], ['Prop', 'suggestion']];
const LEVEL_WORDS: Readonly<Record<KoLevel, string>> = { Haera: 'plain (해라체)', Hae: 'informal (해체)', Haeyo: 'polite (해요체)', Hasipsio: 'formal (하십시오체)' };
const TENSES: readonly KoTense[] = ['Pres', 'Past', 'Fut'];

/** The ending chains (alternatives; the first is the one shown) that fill a slot for a word of this kind; undefined: the slot does not exist for it. */
export function koSlotChains(slot: string, row: Pick<KoRow, 'cat' | 'honSi' | 'stem'>, hon: boolean): string[][] | undefined {
  const { honSi } = row;
  // an honorific existential follows the descriptive table (있으신, 있으시냐, 있으신데), as the dictionary's honorific block does
  const cat: KoCat = row.cat === 'E' && hon ? 'A' : row.cat;
  const p = slot.split(':');
  const H = hon ? ['p-hon'] : [];
  const action = cat === 'V'; // an action verb takes -는다, -느냐, -는; 있다 / 없다 take the 는-forms of a connective and a question only
  switch (p[0]) {
    case 'stem': return undefined;
    case 'fin': {
      const [, mood, level, tense] = p as [string, KoMood, KoLevel, KoTense];
      const pre = tense === 'Past' ? ['p-past'] : tense === 'Fut' ? ['p-fut'] : [];
      if (mood === 'Imp' || mood === 'Prop') {
        if (cat !== 'V' || tense !== 'Pres') return undefined;
        if (mood === 'Imp') {
          // 가다, 오다 and their compounds also have 가거라, 오너라
          if (level === 'Haera') return hon ? [['p-hon', 'imp-eura']] : row.stem.endsWith('가') ? [['imp-ara'], ['imp-geora']] : row.stem.endsWith('오') ? [['imp-ara'], ['imp-neora']] : [['imp-ara']];
          if (level === 'Hae') return [[...H, 'hae']];
          if (level === 'Haeyo') return hon ? [['seyo'], ['p-hon', 'haeyo']] : [['haeyo']];
          return hon ? [['imp-sipsio']] : [['imp-bsio']];
        }
        // the honorific suggestion is shown only at the formal level (먹으십시다); 먹으시자, 먹으셔, 먹으세요 are the honorific forms of the plain, informal and polite endings the table already lists
        if (hon && level !== 'Hasipsio') return undefined;
        if (level === 'Haera') return [['prop-ja']];
        if (level === 'Hae') return [['hae']];
        if (level === 'Haeyo') return [['haeyo']];
        return hon ? [['p-hon', 'prop-bsida']] : [['prop-bsida']];
      }
      if (mood === 'Int' && tense === 'Fut') return undefined;
      if (level === 'Haera') {
        if (mood === 'Ind') return [[...H, ...pre, action && tense === 'Pres' ? 'decl-neunda' : 'decl-da']];
        return [[...H, ...pre, tense === 'Past' || action || cat === 'E' ? 'q-neunya' : 'q-nya']];
      }
      if (level === 'Hae') return [[...H, ...pre, (cat === 'C' || cat === 'N') && tense === 'Pres' && !hon ? 'hae-ya' : 'hae']];
      if (level === 'Haeyo') {
        if (hon && tense === 'Pres') return honSi ? undefined : [['seyo'], ['p-hon', 'haeyo']];
        return [[...H, ...pre, 'haeyo']];
      }
      return [[...H, ...pre, mood === 'Ind' ? 'hasipsio-decl' : 'hasipsio-q']];
    }
    case 'conn': {
      const id = p[1];
      switch (id) {
        case 'and': return [[...H, 'and']];
        case 'so': return [[...H, cat === 'C' ? 'so-ra' : 'so']];
        case 'if': return [[...H, 'if']];
        case 'but': return [[...H, 'but']];
        case 'because': return [[...H, 'because']];
        case 'since': return [[...H, 'since']];
        case 'only-if': return [[...H, 'only-if']];
        case 'background': return [[...H, cat === 'V' || cat === 'E' ? 'background' : 'background-adj']];
        case 'and-then': return [[...H, 'deoni']];
        case 'intend': return cat === 'V' ? [[...H, 'intend']] : undefined;
        case 'inf': return cat === 'C' || cat === 'N' ? undefined : [[...H, 'inf']];
      }
      return undefined;
    }
    case 'adn':
      switch (p[1]) {
        // 계시다: its -(으)ㄴ is the present state (계신 곳, where one is), which the analyser reads as the present
        case 'pres': return row.stem === '계시' ? [[...H, 'adn-neun'], [...H, 'adn-n']] : [[...H, cat === 'V' || cat === 'E' ? 'adn-neun' : 'adn-n']];
        case 'past': return cat === 'V' && row.stem !== '계시' ? [[...H, 'adn-n']] : undefined;
        case 'prosp': return [[...H, 'adn-l']];
        case 'retro': return [[...H, 'adn-deon']];
      }
      return undefined;
    case 'nmlz': {
      const past = p[2] === 'past' ? ['p-past'] : [];
      return [[...H, ...past, p[1] === 'gi' ? 'nmlz-gi' : 'nmlz-m']];
    }
  }
  return undefined;
}

/** The slots of a predicate table, in display order. */
export function koPredicateSlots(): string[] {
  const out = ['stem:base', 'stem:eu', 'stem:aeo'];
  for (const [mood] of MOODS) for (const level of KO_LEVELS) for (const tense of TENSES) out.push(`fin:${mood}:${level}:${tense}`);
  for (const [id] of KO_CONNECTIVE_SLOTS) out.push(`conn:${id}`);
  out.push('adn:pres', 'adn:past', 'adn:prosp', 'adn:retro', 'nmlz:gi', 'nmlz:m', 'nmlz:gi:past', 'nmlz:m:past');
  return out;
}

const gen = (row: KoRow, chains: readonly string[][], vowelNoun = false): string[] => {
  const out: string[] = [];
  for (const ch of chains) for (const f of koGenerate(row.stem, row.cls, ch.map(koEnding), { honSi: row.honSi, ...(vowelNoun ? { vowelNoun: true } : {}) })) {
    if (!out.includes(f)) out.push(f);
  }
  return out;
};

/** Put the form a speaker would write first: 계세요 before 계셔요, 이에요 before 이어요, 해요 before 하여요 (the engine lists the contracted form first already). */
function usual(forms: string[], row: KoRow, slot: string): string[] {
  const rank = (f: string): number => {
    if (row.honSi && slot.endsWith(':Haeyo:Pres') && /세요$/u.test(f)) return -1;
    if ((row.cat === 'C' || row.cat === 'N') && /에요$/u.test(f)) return -1;
    return 0;
  };
  return forms.map((f, i) => [f, i, rank(f)] as const).sort((a, b) => a[2] - b[2] || a[1] - b[1]).map((x) => x[0]);
}

const ROLE = (id: string): string => koEnding(id).role;

function cellNote(slot: string, cat: KoCat, chains: string[][]): string | undefined {
  const p = slot.split(':');
  const first = chains[0];
  const last = first[first.length - 1];
  if (p[0] === 'conn') return `${koEnding(last).cite}: ${ROLE(last)}`;
  if (p[0] === 'adn') {
    const verb = cat === 'V' || cat === 'E';
    if (p[1] === 'pres') return verb ? 'before a noun, present (-는): the one who eats' : 'before a noun, present state (-(으)ㄴ): pretty, is …';
    if (p[1] === 'past') return 'before a noun, past (-(으)ㄴ): the one who ate';
    if (p[1] === 'prosp') return 'before a noun, not yet (-(으)ㄹ): the one who will eat';
    return 'before a noun, recalled (-던): the one who used to …';
  }
  if (p[0] === 'nmlz') return `${p[1] === 'gi' ? '-기' : '-(으)ㅁ'}: ${p[1] === 'gi' ? 'doing, to do' : 'the fact of …'}${p[2] === 'past' ? ' (past)' : ''}`;
  if (p[0] === 'fin' && p[1] === 'Imp' && p[2] === 'Hasipsio' && !first.includes('p-hon') && last === 'imp-bsio') return '-(으)ㅂ시오 is used on notices; the usual polite command is the honorific -(으)십시오';
  return undefined;
}

const stemShapeNote: Readonly<Record<string, string>> = {
  base: 'the stem: the dictionary form without -다 (before -고, -지, -는, -네 …)',
  eu: 'before -(으)면, -(으)니까, -(으)ㄴ, -(으)ㄹ, -(으)세요 … (a stem ending in ㄹ keeps it before -(으)면 and drops it before -(으)니까, -(으)세요, -ㅂ니다)',
  aeo: 'before -아/어 endings: -아/어요, -아/어서, -았/었다 … (the infinitive)',
};

// ───────────────────────────── the table of one entry ─────────────────────────────

interface RowCells {
  row: KoRow;
  /** slot → forms by column. */
  forms: Map<string, { plain: string[]; hon: string[] }>;
}

function predicateForms(row: KoRow): RowCells {
  const forms = new Map<string, { plain: string[]; hon: string[] }>();
  if (row.cls !== 'Cop' && row.cls !== 'Neg') {
    const bases = koJunctionBases(row.stem, row.cls);
    forms.set('stem:base', { plain: [bases.bare], hon: [] });
    if (bases.eu.length) forms.set('stem:eu', { plain: [...new Set(bases.eu)], hon: [] });
    if (bases.aeo.length) forms.set('stem:aeo', { plain: [...new Set(bases.aeo)], hon: [] });
  }
  for (const slot of koPredicateSlots()) {
    if (slot.startsWith('stem:')) continue;
    const plainChains = koSlotChains(slot, row, false);
    const honChains = row.honSi ? undefined : koSlotChains(slot, row, true);
    const plain = plainChains ? usual(gen(row, plainChains), row, slot) : [];
    const hon = honChains ? usual(gen(row, honChains), row, slot) : [];
    if (plain.length || hon.length) forms.set(slot, { plain, hon });
  }
  return { row, forms };
}

// ───────────────────────────── labels, class names ─────────────────────────────

const CLASS_WORDS: Readonly<Record<string, string>> = {
  D: 'ㄷ-irregular: the final ㄷ becomes ㄹ before a vowel',
  B: 'ㅂ-irregular: the final ㅂ becomes 우 (or 와) before a vowel',
  S: 'ㅅ-irregular: the final ㅅ drops before a vowel',
  H: 'ㅎ-irregular: the final ㅎ drops, and the vowel changes before 아/어',
  Reu: '르-irregular: 르 becomes ㄹㄹ before 아/어',
  Reo: '러-irregular: the infinitive is -러, not -어',
  U: '우-irregular: the 우 drops before 어',
  Ha: '하다 verb: 하 + 여 contracts to 해 (or stays 하여)',
  Cop: 'the copula 이다: it follows a noun and drops its 이 after a vowel (의사다, 의사예요)',
  Neg: 'the negative copula 아니다 (follows 이/가 + noun)',
};

function classWords(row: KoRow): { template: string; note: string } {
  const b = koJunctionBases(row.stem, row.cls);
  const shapes = `stem ${row.stem} → ${b.eu.join(' / ')} (before -(으)X) and ${b.aeo.join(' / ')} (before -아/어)`;
  if (CLASS_WORDS[row.cls]) {
    const template = row.cls === 'Cop' ? 'copula 이다' : row.cls === 'Neg' ? 'copula 아니다' : row.cls === 'Ha' ? '하다 verb' : `${row.cls === 'Reu' ? '르' : row.cls === 'Reo' ? '러' : row.cls === 'U' ? '우' : row.cls === 'D' ? 'ㄷ' : row.cls === 'B' ? 'ㅂ' : row.cls === 'S' ? 'ㅅ' : 'ㅎ'}-irregular`;
    return { template, note: `${CLASS_WORDS[row.cls]} (${shapes}).` };
  }
  const last = [...row.stem].pop()!;
  const d = decompose(last);
  if (d && FINALS[d.t] === 'ㄹ') {
    const ex = [koGenerate(row.stem, row.cls, [koEnding('adn-neun')])[0], koGenerate(row.stem, row.cls, [koEnding('hasipsio-decl')])[0]].filter(Boolean).join(', ');
    return { template: 'regular (ㄹ-stem)', note: `Regular. The stem ends in ㄹ, which drops before ㄴ, ㅂ, ㅅ and 오 (${ex}) (${shapes}).` };
  }
  if (d && VOWELS[d.v] === 'ㅡ' && d.t === 0) return { template: 'regular (ㅡ-stem)', note: `Regular. The ㅡ of the last syllable drops before 아/어 (${shapes}).` };
  return { template: 'regular', note: `Regular (${shapes}).` };
}

const catWords = (cat: KoCat): string => cat === 'V' ? 'an action verb' : cat === 'A' ? 'a descriptive verb (an adjective: it has no -는다, no command and no suggestion)' : cat === 'E' ? 'an existential (있다, 없다: descriptive in the plain present, with the -는 forms of a verb: 있는, 있는데)' : cat === 'C' ? 'the copula' : 'the negative copula';

function slotLabel(slot: string, cat: KoCat): string {
  const p = slot.split(':');
  const verb = cat === 'V' || cat === 'E';
  switch (p[0]) {
    case 'stem': return p[1] === 'base' ? 'stem (the word without -다)' : p[1] === 'eu' ? 'stem before -(으)X endings' : 'stem before -아/어 (the infinitive)';
    case 'fin': {
      const mood = MOODS.find(([m]) => m === p[1])![1];
      const tense = p[3] === 'Pres' ? (p[1] === 'Ind' || p[1] === 'Int' ? 'present' : '') : p[3] === 'Past' ? 'past (-았/었-)' : 'will, must (-겠-)';
      return [mood, LEVEL_WORDS[p[2] as KoLevel], tense].filter(Boolean).join(' · ');
    }
    case 'conn': { const c = KO_CONNECTIVE_SLOTS.find(([id]) => id === p[1])!; return `connective ${c[1]} · ${c[2]}`; }
    case 'adn':
      return p[1] === 'pres' ? (verb ? 'before a noun · present -는' : 'before a noun · present -(으)ㄴ')
        : p[1] === 'past' ? 'before a noun · past -(으)ㄴ'
        : p[1] === 'prosp' ? 'before a noun · to come -(으)ㄹ' : 'before a noun · recalled -던';
    case 'nmlz': return `as a noun · ${p[1] === 'gi' ? '-기' : '-(으)ㅁ'}${p[2] === 'past' ? ' after the past (-았/었-)' : ''}`;
  }
  return slot;
}

// ───────────────────────────── the generated paradigm of a predicate ─────────────────────────────

interface Context {
  lemma: string;
  groups: Array<{ entry?: string; cells: RowCells }>;
  multi: boolean;
  /** The honorific base of the first group (먹으): a form that starts with it and continues with a 시-syllable is honorific in shape. */
  honBase?: string;
}
let CONTEXT: Context | undefined;
/** For tests and callers that must start clean. */
export const koClearParadigmContext = (): void => { CONTEXT = undefined; };

const HON_SYLLABLES = '시셔셨세신실십심';
const signature = (r: KoRow): string => `${r.cls}|${r.cat}|${r.honSi ? 1 : 0}`;

function predicateParadigm(lemma: string, pos: PartOfSpeech): GeneratedParadigm | undefined {
  const { rows, refused } = koPredicateRows(lemma, pos);
  if (!rows.length) return undefined;
  const groupsBySig = new Map<string, KoRow[]>();
  for (const r of rows) groupsBySig.set(signature(r), [...(groupsBySig.get(signature(r)) ?? []), r]);
  const groups = [...groupsBySig.values()];
  const multi = groups.length > 1;
  const cells: GeneratedParadigm['cells'] = [];
  const ctxGroups: Context['groups'] = [];
  const slotsPresent = new Set<string>();
  let hasHon = false;
  const entryLabels: Record<string, string> = {};
  for (const g of groups) {
    const row = g[0];
    const rc = predicateForms(row);
    const entry = multi ? row.shown : undefined;
    if (entry) entryLabels[entry] = `${g.map((r) => r.shown).join(' / ')}${row.gloss ? `: ${row.gloss}` : ''} (${classWords(row).template})`;
    ctxGroups.push({ ...(entry ? { entry } : {}), cells: rc });
    for (const slot of koPredicateSlots()) {
      const f = rc.forms.get(slot);
      if (!f) continue;
      for (const hon of [false, true]) {
        const forms = hon ? f.hon : f.plain;
        if (!forms.length) continue;
        const features = koCellFeatures(slot, hon)!;
        if (entry) features.Entry = entry;
        const chains = slot.startsWith('stem:') ? [['x']] : koSlotChains(slot, row, hon)!;
        const note = slot.startsWith('stem:') ? stemShapeNote[slot.slice(5)] : cellNote(slot, row.cat, chains);
        let extra: string | undefined;
        if (row.cls === 'Cop' && !slot.startsWith('stem:')) {
          const v = gen(row, chains, true).filter((x) => !forms.includes(x));
          if (v.length) extra = `after a vowel-final noun: ${v.join(', ')}`;
        }
        const noteText = [note, extra].filter(Boolean).join('; ') || undefined;
        forms.forEach((form, i) => cells.push({ features, form, ...(i === 0 && noteText ? { note: noteText } : {}) }));
        slotsPresent.add(slot);
        if (hon) hasHon = true;
      }
    }
  }
  if (!cells.length) return undefined;
  const first = rows[0];
  // the honorific base of the first group, to judge the shape of a dictionary row nothing generated spells
  const hb = !first.honSi ? koGenerate(first.stem, first.cls, [koEnding('p-hon'), koEnding('and')], {})[0] : undefined;
  CONTEXT = { lemma, groups: ctxGroups, multi, ...(hb ? { honBase: hb.slice(0, -2) } : {}) };

  const rowSlots = koPredicateSlots().filter((s) => slotsPresent.has(s));
  const rowLabels: Array<[string, string]> = rowSlots.map((s) => [s, slotLabel(s, first.cat)]);
  const layout: ParadigmLayout = {
    columns: { key: 'Honorific', values: hasHon ? [['No', 'plain'], ['Subj', 'honorific -(으)시-']] : [['No', 'plain']] },
    rows: { key: 'Slot', values: rowLabels },
    ...(multi ? { sections: ['Entry'], labels: { Entry: entryLabels } } : {}),
  };

  const notes: string[] = [];
  const kindWords = catWords(first.cat);
  if (multi) {
    notes.push(`${koBareLemma(lemma)} names ${rows.length} entries that do not conjugate alike, so there is one table for each (${Object.values(entryLabels).join('; ')}). Nothing is chosen for you: the sentence decides which entry is meant.`);
    for (const g of groups) notes.push(`${g.map((r) => r.shown).join(' / ')}: ${classWords(g[0]).note} It is ${catWords(g[0].cat)}.`);
  } else {
    if (rows.length > 1) notes.push(`${koBareLemma(lemma)} names ${rows.length} entries (${rows.map((r) => r.shown + (r.gloss ? ` ${r.gloss}` : '')).join('; ')}) that conjugate identically, so one table serves them all.`);
    notes.push(`${classWords(first).note} It is ${kindWords}.`);
  }
  if (first.entry.own && !first.gloss) notes.push(`${koBareLemma(lemma)} has no entry of its own in the lexicon: it is read as a noun or root plus its light verb (${first.cls === 'Ha' ? '하다' : '되다 / 시키다'}) and conjugates as that verb does.`);
  if (first.honSi) notes.push('This verb is itself honorific, so it has no further -(으)시- column; 시 + 어요 contracts to 세요 (계세요).');
  if (first.cat === 'V') notes.push('Before a noun an action verb shows tense: 먹는 (present) · 먹은 (past) · 먹을 (to come); a descriptive verb shows the present state: 예쁜.');
  notes.push('Each form is generated by rule from the dictionary entry\'s conjugation class and read back through the analyser; a form the dictionary\'s table also gives is marked as agreeing, one it spells differently is marked as a disagreement with both shown.');
  for (const r of refused) notes.push(`Left out: ${r}.`);
  return {
    kind: 'verb-conjugation',
    cells,
    layout,
    ...(multi ? {} : { template: classWords(first).template }),
    notes,
  };
}

// ───────────────────────────── nouns, pronouns, numerals ─────────────────────────────

const NOMINAL_POS = new Set(['NOUN', 'PROPN', 'PRON', 'NUM', 'CLF']);
const NOUN_TAGS: Readonly<Record<string, readonly string[]>> = { NOUN: ['NNG', 'NNB'], PROPN: ['NNP'], PRON: ['NP'], NUM: ['NR'], CLF: ['NNB'] };

/** The particles of the noun table, with the row's plain label. */
const NOUN_PARTICLES: ReadonlyArray<readonly [id: string, label: string]> = [
  ['subject', 'subject 이/가'], ['topic', 'topic 은/는'], ['object', 'object 을/를'], ['of', 'of 의'], ['to', 'to, at (a time or a destination) 에'],
  ['at', 'at, from (a place) 에서'], ['by', 'by, toward 로/으로'], ['and', 'and, with 와/과'], ['also', 'also 도'], ['only', 'only 만'],
];
/** A pronoun that changes shape before a particle: 나 + 가 = 내가. */
const FUSED_NOMINAL: Readonly<Record<string, Readonly<Record<string, string>>>> = {
  나: { subject: '내가', of: '내' }, 저: { subject: '제가', of: '제' }, 너: { subject: '네가', of: '네' }, 누구: { subject: '누가' },
};

const hostSound = (word: string): 'V' | 'L' | 'C' => {
  const d = decompose([...word].pop() ?? '');
  if (!d || d.t === 0) return 'V';
  return FINALS[d.t] === 'ㄹ' ? 'L' : 'C';
};

/** The allomorph of a particle for a host, or undefined. */
function particleForm(id: string, host: 'V' | 'L' | 'C'): string | undefined {
  const p = PARTICLES[id];
  return p?.forms.find((f) => koAllomorphAgrees(f.after, host))?.text;
}

const COPULA_SLOTS: ReadonlyArray<readonly [slot: string, level: KoLevel, tense: KoTense, chain: string[]]> = [
  ['cop:Haera:Pres', 'Haera', 'Pres', ['decl-da']], ['cop:Haeyo:Pres', 'Haeyo', 'Pres', ['haeyo']], ['cop:Hasipsio:Pres', 'Hasipsio', 'Pres', ['hasipsio-decl']],
  ['cop:Haera:Past', 'Haera', 'Past', ['p-past', 'decl-da']], ['cop:Haeyo:Past', 'Haeyo', 'Past', ['p-past', 'haeyo']], ['cop:Hasipsio:Past', 'Hasipsio', 'Past', ['p-past', 'hasipsio-decl']],
];

/** The entries a nominal lemma names (a bare spelling of a balanced set: all of them), bound allomorphs left out. */
export function koNominalRows(lemma: string, pos: string): KoLexEntry[] {
  const bare = koBareLemma(lemma);
  const tags = NOUN_TAGS[pos];
  if (!tags) return [];
  const hits = lookupKoreanStem(bare).map((h) => h.entry).filter((e) => e.lemma === bare && tags.includes(e.tag) && koSharedPos(e) === pos);
  const numbered = koHomonymNumber(lemma) !== undefined;
  const chosen = hits.filter((e) => koEntryLemma(e) === lemma);
  return (chosen.length ? chosen : numbered ? [] : hits).filter((e) => !e.bound);
}

function nominalParadigm(lemma: string, pos: PartOfSpeech): GeneratedParadigm | undefined {
  const entries = koNominalRows(lemma, pos);
  if (!entries.length) return undefined;
  const bare = koBareLemma(lemma);
  const cells: GeneratedParadigm['cells'] = [];
  const rowLabels: Array<[string, string]> = [['p:none', 'the word itself']];
  // 저 "I" is 제가 but 저 "that" is 저가: the fused form leads only when every entry of the spelling is the pronoun that fuses
  const fusing = (e: KoLexEntry) => /\b(?:I|me|you|who)\b/u.test(e.gloss ?? '');
  const fused = entries.some(fusing) ? FUSED_NOMINAL[bare] ?? {} : {};
  const fusedFirst = entries.every(fusing);
  const plural = `${bare}들`;
  const sound = hostSound(bare);
  const push = (slot: string, particle: string, number: 'Sing' | 'Plur', form: string, note?: string) => {
    cells.push({ features: { Slot: slot, Particle: particle, Number: number, ...(particle !== 'none' ? PARTICLES[particle].morph : {}) }, form, ...(note ? { note } : {}) });
  };
  push('p:none', 'none', 'Sing', bare);
  push('p:none', 'none', 'Plur', plural, 'plural -들 (optional; Korean does not mark the plural unless it matters)');
  for (const [id, label] of NOUN_PARTICLES) {
    const f = particleForm(id, sound);
    const fp = particleForm(id, 'L');
    if (!f || !fp) continue;
    rowLabels.push([`p:${id}`, label]);
    const forms = fused[id] ? (fusedFirst ? [fused[id], bare + f] : [bare + f, fused[id]]) : [bare + f];
    forms.forEach((form, i) => push(`p:${id}`, id, 'Sing', form, i === 0 ? PARTICLES[id].role : undefined));
    push(`p:${id}`, id, 'Plur', plural + fp, PARTICLES[id].role);
  }
  {
    const row: KoRow = { lemma: '이다', shown: '이다', stem: '이', cls: 'Cop', cat: 'C', honSi: false, entry: { lemma: '이다', tag: 'VCP' } };
    for (const [slot, level, tense, chain] of COPULA_SLOTS) {
      // after a vowel the contracted form is the usual one (의사다, 의사예요, 의사였어요); after a consonant 학생이에요, with 이어요 the uncontracted variant
      const raw = gen(row, [chain], sound === 'V');
      const contracted = (f: string): number => (/[에예]요$/u.test(f) ? 0 : 1);
      const alts = sound === 'V' ? [...raw].sort((a, b) => a.length - b.length || contracted(a) - contracted(b)) : usual(raw, row, slot);
      if (!alts.length) continue;
      rowLabels.push([slot, `${bare} + copula 이다 · ${LEVEL_WORDS[level]} · ${tense === 'Pres' ? 'present' : 'past'}`]);
      alts.forEach((f, i) => cells.push({ features: { Slot: slot, VerbType: 'Cop', VerbForm: 'Fin', Mood: 'Ind', SpeechLevel: level, Tense: tense, Number: 'Sing' }, form: bare + f, ...(i === 0 ? { note: `${bare} is …; the copula 이다 is written with the noun` } : {}) }));
    }
  }
  const notes = [
    `${bare}: a noun-like word has no inflection; the table shows the common particles, each in the shape its last sound asks for (${sound === 'V' ? 'after a vowel: 가, 는, 를, 로 …' : sound === 'L' ? 'after ㄹ: 이, 은, 을, 로 …' : 'after a consonant: 이, 은, 을, 으로 …'}), and the copula 이다 that makes it a statement (학생이다 · 의사다).`,
    'The dictionary gives no table of particle forms for a noun, so every cell here comes from the analyser\'s rules and is marked as such.',
  ];
  if (fused.subject) notes.push(fusedFirst ? `${bare} + 가 is written ${fused.subject}; the plain ${bare}가 is not used.` : `${bare} + 가 is written ${fused.subject} when ${bare} is the pronoun (${entries.filter(fusing).map((e) => koEntryLemma(e)).join(', ')}).`);
  if (entries.length > 1) notes.push(`${bare} names ${entries.length} entries (${entries.map((e) => koEntryLemma(e) + (e.gloss ? ` ${e.gloss}` : '')).join('; ')}); particles attach to all of them alike.`);
  return {
    kind: pos === 'PRON' ? 'pronoun-paradigm' : 'noun-declension',
    cells,
    layout: { columns: { key: 'Number', values: [['Sing', 'singular'], ['Plur', 'with plural -들']] }, rows: { key: 'Slot', values: rowLabels } },
    notes,
  };
}

// ───────────────────────────── the adapter's members ─────────────────────────────

export function koParadigm(lemma: string, pos: PartOfSpeech, _hint?: { features?: Record<string, string>; surface?: string }): GeneratedParadigm | undefined {
  CONTEXT = undefined;
  if (typeof lemma !== 'string' || !lemma) return undefined;
  if (NOMINAL_POS.has(pos)) return nominalParadigm(lemma, pos);
  if (pos === 'VERB' || pos === 'ADJ' || pos === 'AUX') return predicateParadigm(lemma, pos);
  return undefined;
}

/**
 * The dictionary table's tags for one row → the paradigm's features. Context-free: the plain cell of the slot. With the lemma's
 * generated forms in `CONTEXT` (the call that just built the generated half), a row is placed in the plain or the honorific cell
 * (and, for a bare lemma of several conjugation classes, the entry) whose generated form it spells; a row neither spells goes by its
 * shape. `undefined`: the tags name no cell, or the form is an unfilled template.
 */
export function koFeaturesFromTableTags(tags: readonly string[], _pos: PartOfSpeech, form?: string): Record<string, string> | undefined {
  const base = koFeaturesFromTableTagsPlain(tags, form);
  if (!base) return undefined;
  const ctx = CONTEXT;
  if (!ctx || form === undefined) return base;
  const slot = base.Slot;
  const find = (hon: boolean) => ctx.groups.find((g) => (hon ? g.cells.forms.get(slot)?.hon : g.cells.forms.get(slot)?.plain)?.includes(form));
  const plain = find(false);
  const honG = find(true);
  const withEntry = (f: Record<string, string>, entry?: string): Record<string, string> => (ctx.multi && entry ? { ...f, Entry: entry } : f);
  if (plain) return withEntry(base, plain.entry);
  if (honG) return withEntry(koCellFeatures(slot, true)!, honG.entry);
  // nothing generated spells the form: by shape
  const g0 = ctx.groups[0];
  const slotHasHon = (g0.cells.forms.get(slot)?.hon.length ?? 0) > 0;
  const shaped = !!ctx.honBase && slotHasHon && form.startsWith(ctx.honBase) && HON_SYLLABLES.includes(form[ctx.honBase.length] ?? '');
  return withEntry(shaped ? koCellFeatures(slot, true)! : base, g0.entry);
}

